import math

class DataStatistics4:

    TWO_PI = 2 * math.pi
    HALF = 0.5

    @staticmethod
    def _calculate_mean(data):
        return sum(data) / len(data)

    @staticmethod
    def _calculate_variance(data, mean):
        return sum((x - mean) ** 2 for x in data) / len(data)

    @staticmethod
    def _centered_data(data, mean):
        return [x - mean for x in data]

    @staticmethod
    def correlation_coefficient(data1, data2):
        n = len(data1)
        mean1 = DataStatistics4._calculate_mean(data1)
        mean2 = DataStatistics4._calculate_mean(data2)

        numerator = sum((data1[i] - mean1) * (data2[i] - mean2) for i in range(n))
        denominator = math.sqrt(sum((data1[i] - mean1) ** 2 for i in range(n))) * math.sqrt(sum((data2[i] - mean2) ** 2 for i in range(n)))

        if denominator == 0:
            return 0
        return numerator / denominator

    @staticmethod
    def skewness(data):
        n = len(data)
        mean = DataStatistics4._calculate_mean(data)
        std_deviation = math.sqrt(DataStatistics4._calculate_variance(data, mean))

        if std_deviation == 0 or n <= 2:
            return 0

        centered = DataStatistics4._centered_data(data, mean)
        return sum(c ** 3 for c in centered) * n / ((n - 1) * (n - 2) * std_deviation ** 3)

    @staticmethod
    def kurtosis(data):
        n = len(data)
        mean = DataStatistics4._calculate_mean(data)
        std_dev = math.sqrt(DataStatistics4._calculate_variance(data, mean))

        if std_dev == 0:
            return math.nan

        centered = DataStatistics4._centered_data(data, mean)
        fourth_moment = sum(x ** 4 for x in centered) / n

        return (fourth_moment / std_dev ** 4) - 3

    @staticmethod
    def pdf(data, mu, sigma):
        if sigma == 0:
            return [0] * len(data)
        constant = 1 / (sigma * math.sqrt(DataStatistics4.TWO_PI))
        return [constant * math.exp(-DataStatistics4.HALF * ((x - mu) / sigma) ** 2) for x in data]
